<?php
require_once __DIR__.'/../includes/auth.php';requireLogin();$u=currentUser();if(isPost()){verifyCsrf();$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT user_id,status FROM news WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);$a=$s->fetch();if($a&&canEditArticle($a)){db()->prepare('UPDATE news SET deleted_at=NOW() WHERE id=?')->execute([$id]);flash('success','تم نقل الخبر إلى المحذوفات.');}redirect(url('admin/news.php'));}
$where=['n.deleted_at IS NULL'];$args=[];if($u['role']==='author'){$where[]='n.user_id=?';$args[]=$u['id'];}if($q=trim($_GET['q']??'')){$where[]='n.title LIKE ?';$args[]="%{$q}%";}if($status=$_GET['status']??''){$where[]='n.status=?';$args[]=$status;}if($cat=(int)($_GET['category']??0)){$where[]='n.category_id=?';$args[]=$cat;}$sqlWhere=implode(' AND ',$where);$c=db()->prepare("SELECT COUNT(*) FROM news n WHERE {$sqlWhere}");$c->execute($args);[$page,$pages,$offset]=paginate((int)$c->fetchColumn());$s=db()->prepare("SELECT n.*,c.name category,u.name author FROM news n LEFT JOIN categories c ON c.id=n.category_id LEFT JOIN users u ON u.id=n.user_id WHERE {$sqlWhere} ORDER BY n.created_at DESC LIMIT 10 OFFSET {$offset}");$s->execute($args);$rows=$s->fetchAll();$cats=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$pageTitle='كل الأخبار';require __DIR__.'/includes/header.php';?>
<div class="card stat-card"><div class="card-body"><form class="row g-2 mb-4"><div class="col-md-5"><input class="form-control" name="q" placeholder="بحث بالعنوان" value="<?=e($_GET['q']??'')?>"></div><div class="col-md-3"><select class="form-select" name="category"><option value="">كل التصنيفات</option><?php foreach($cats as $x):?><option value="<?=$x['id']?>" <?=($_GET['category']??'')==$x['id']?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="status"><option value="">كل الحالات</option><?php foreach(['draft','pending','published','archived'] as $x):?><option value="<?=$x?>" <?=($_GET['status']??'')===$x?'selected':''?>><?=statusLabel($x)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">تصفية</button></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>الصورة</th><th>العنوان</th><th>التصنيف</th><th>الكاتب</th><th>الحالة</th><th>المشاهدات</th><th>التاريخ</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><img src="<?=imageUrl($r['image'])?>"></td><td class="fw-semibold"><?=e($r['title'])?></td><td><?=e($r['category']??'—')?></td><td><?=e($r['author']??'—')?></td><td><span class="badge text-bg-<?=statusClass($r['status'])?>"><?=statusLabel($r['status'])?></span></td><td><?=$r['views_count']?></td><td><?=formatDate($r['created_at'])?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="<?=url('admin/edit-news.php?id='.$r['id'])?>"><i class="bi bi-pencil"></i></a><form class="d-inline" method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="نقل الخبر إلى المحذوفات؟"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="text-center py-5 text-secondary">لا توجد أخبار مطابقة.</td></tr><?php endif;?></tbody></table></div><?=paginationLinks($page,$pages)?></div></div><?php require __DIR__.'/includes/footer.php';?>
